/* Les noms des journées types, les étapes et les suggestions sont aussi des textes, rangés par clé */
['adulte', 'enfant'].forEach(p => {
  V.JOURNEES[p].forEach(q => { V.TEXTES['journee.' + p + '.' + q[0]] = ['camp', q[1], p]; });
  Object.keys(V.SUGGESTIONS[p]).forEach(c => V.SUGGESTIONS[p][c].forEach((s, i) => { V.TEXTES['sugg.' + p + '.' + c + '.' + (i + 1)] = ['cr1', s[0], p]; }));
});
Object.keys(V.ETAPES).forEach(k => V.ETAPES[k].forEach((t, i) => { V.TEXTES['etape.' + k + '.' + (i + 1)] = ['etapes', t, k.split('.')[0]]; }));

